test_randomized_replay()
{
	root_dir=$work/randomized-replay
	mkdir "$root_dir"
	iteration=0
	while [ "$iteration" -lt "$RANDOM_CASES" ]; do
		case_dir=$root_dir/$iteration
		mkdir "$case_dir"
		random_number
		case $((RANDOM_VALUE % 3)) in
		0) block_size=1024 ;;
		1) block_size=2048 ;;
		2) block_size=4096 ;;
		esac
		random_number
		case $((RANDOM_VALUE % 3)) in
		0) open_command=journal_open ;;
		1) open_command='journal_open -c -v 2' ;;
		2) open_command='journal_open -c -v 3' ;;
		esac
		random_number
		count=$((1 + RANDOM_VALUE % 16))
		# TODO: fsck_ext4fs currently rejects e2fsprogs checksum-v2
		# descriptors with multiple tags.  Keep randomized v2 cases
		# single-tag until that parser bug has a dedicated fix.
		[ "$open_command" != 'journal_open -c -v 2' ] || count=1
		random_number
		gap=$((RANDOM_VALUE % 16))
		create_image "$case_dir/image" "$block_size"
		find_free_blocks "$case_dir/image" $((count + gap))
		target=$((FREE_FIRST + gap))
		last=$((target + count - 1))
		if [ "$count" -eq 1 ]; then
			range=$target
		else
			range=$target-$last
		fi
		make_random_payload "$case_dir/payload" "$block_size" "$count"
		printf 'seed=%s block_size=%s format=%s count=%s target=%s\n' \
		    "$JOURNAL_SEED" "$block_size" "$open_command" "$count" \
		    "$range" >"$case_dir/parameters"
		{
			printf '%s\n' "$open_command"
			printf 'journal_write -b %s %s\n' "$range" "$case_dir/payload"
			printf 'journal_close\n'
		} >"$case_dir/debugfs.cmd"
		run_debugfs "$case_dir/image" "$case_dir/debugfs.cmd"
		replay "$case_dir/image"
		compare_blocks "$case_dir/image" "$block_size" "$target" "$count" \
		    "$case_dir/payload"
		verify_e2fsck "$case_dir/image"
		iteration=$((iteration + 1))
	done
}

test_randomized_mutations()
{
	root_dir=$work/randomized-mutations
	mkdir "$root_dir"
	case_dir=$root_dir/base
	mkdir "$case_dir"
	create_image "$case_dir/image" 4096
	find_free_blocks "$case_dir/image" 8
	make_random_payload "$case_dir/payload" 4096 8
	{
		printf 'journal_open -c -v 3\n'
		printf 'journal_write -b %s %s\n' "$FREE_RANGE" \
		    "$case_dir/payload"
		printf 'journal_close\n'
	} >"$case_dir/debugfs.cmd"
	run_debugfs "$case_dir/image" "$case_dir/debugfs.cmd"
	base_image=$case_dir/image
	iteration=0
	while [ "$iteration" -lt "$MUTATION_CASES" ]; do
		case_dir=$root_dir/$iteration
		mkdir "$case_dir"
		cp "$base_image" "$case_dir/image"
		case $((iteration % 3)) in
		0) logical=1 ;;
		1) logical=10 ;;
		2) random_number; logical=$((2 + RANDOM_VALUE % 8)) ;;
		esac
		random_number
		case "$logical" in
		1|10)	within=$((12 + RANDOM_VALUE % (4096 - 12))) ;;
		*)	within=$((RANDOM_VALUE % 4096)) ;;
		esac
		random_number
		mask=$((1 << (RANDOM_VALUE % 8)))
		printf 'seed=%s logical=%s offset=%s mask=%s\n' "$JOURNAL_SEED" \
		    "$logical" "$within" "$mask" >"$case_dir/parameters"
		flip_journal_byte "$case_dir/image" "$logical" "$within" "$mask"
		expect_replay_failure_unchanged "$case_dir/image"
		iteration=$((iteration + 1))
	done
}

